    ('gpx/11381.gpx', 'Track-05B Landhuizen en Kastelen tussen De Steeg en Doornenburg', 'Deze routecollectie langs de Nederlandse Landhuizen & Kastelen, bestaat uit 14 routes. 
Deze landhuizen en kastelen zijn als raamwerk gebruikt om de mooie routes uit te zetten, maar ook zonder het bezoeken van de beschreven objecten blijven de routes de moeite waard. Maar de route heeft natuurlijk een meerwaarde als u hier en daar eens afstapt en een wandeling maakt. Niet alle landhuizen en kastelen zijn open voor bezoekers, maar deze zijn dan te spotten vanaf de openbare weg of hun tuin of park is open voor bezoekers.
De route gaat voor het grootste deel over binnenwegen, de drukkere N-wegen en stedelijk gebied worden zoveel mogelijk gemeden. De lengte van de routes zijn onder de 175 km gehouden mede omdat de gemiddelde snelheid niet zo hoog zal liggen op vele 60 km wegen.
Bijna elke provincie heeft één of meer routes, alleen in Zuid-Holland en de Flevopolders zijn geen routes uitgezet omdat daar geen landhuizen en kastelen stonden die voor deze tour in aanmerking kwamen door hun ligging.

Startpunt: Kasteel Middachten, De Steeg
Eindpunt: Kasteel Doornenburg, Doornenburg

Deze 4 sterren route worden u aangeboden door Motorclub Contact Dordrecht.'),
