    ('gpx/13163.gpx', 'Men''s 10K Glasgow', 'Men’s 10K in Glasgow starts at the spectacular setting of the Riverside Transport Museum.

The route heads East along the River Clyde and takes in the scenic views. Iconic buildings to look out for include the Glasgow Science Centre, The Armadillo, The SECC and the SSE Hydro and all within the first 2KM.

The route then heads over the Clyde and back, crossing over the ''Squiggly Bridge'' and then George V Bridge. You will then start heading through the hustle and bustle of Glasgow''s city centre heading up Buchanan Street just before you hit half way!

The second half of the route will take you past the south side of George Square and down towards Glasgow Green, taking in the beautiful park including the infamous People''s Palace, where cheering crowds await to help in one last effort to cross the finish line where you’ll receive your well earned medal, water and goodybag.'),
