    ('gpx/13222.gpx', 'Kilomathon 6.5K', 'Beginning on Clark Road Cycle path just off Ferry Road.

The route joins in with the 13.1K runners as they run along Edinburgh’s tranquil cycle paths, before a breathtaking finish in front of the West Stand in BT Murrayfield Stadium.'),
