    ('gpx/13232.gpx', 'Supernova Forth Road Bridge 5K', 'The iconic Forth Road Bridge will be completely closed for you to walk, jog or run 5k and help change thousands of lives for the better.

Expressions of interest to participate in this event is already unprecedented, and as such, a ballot process will be used to allocate places for this exclusive experience.

If successful in the Supernova Forth Road Bridge ballot, you can look forward to:

Walking, jogging, or running a 5K route, enjoying a series of spectacular light and colour features all the way. The event is completely accessible and therefore suitable for all abilities. You decide your pace, whether that is to run at the speed of light, or take your time and snap a few pictures and selfies as you go!

Your entry includes transport to and from the Forth Road Bridge, with your experience starting at the Event Travel Hub located at Gyle Shopping Centre.

Before you reach that start line, we’ll make sure you’re ready for it by participating in a fun Supernova Warm-up full of easy moves and stretches.

You’ll be given a special LED Supernova head torch to help you light up the night. You can take this home with you afterwards.

After finishing your Supernova Forth Road Bridge experience, you will receive your exclusive Supernova Forth Road Bridge Medal and Finishers pack as a memento of your evening!

When the ballot opens for applications, it will only be for a limited time. Enter now so that you don’t miss your opportunity to be part of this amazing event.'),
