    ('gpx/17021.gpx', 'Estinale', '"Estinale" - 9,78 km - Balise : rectangle blanc sur bleuPoint de départ et arrivée : Eglise d’Erezée (Place Capitaine Garnir)Au départ de la Place Capitaine Garnir, descendre l’escalier se trouvant à côté du panneau de départ de la balade.Dos à l’escalier, partir sur la gauche et suivre la route principale jusqu’au grand virage après la pharmacie. Dans le virage, prendre à droite, vers Oster.&nbsp;Après avoir dépassé le complexe sportif d’Erezée, au bout de la rue, prendre l’Y à droite et directement après l’Y à gauche pour vous enfoncer dans le petit bois de feuillus et résineux.Arrivé au T, vous débouchez au fond d’une petite vallée où serpente un ruisseau,&nbsp;prenez à gauche, pour monter vers Oster.Après deux ou trois cents mètres, vous longez sur votre gauche, des prairies pentues bordées de haies vives. Ayant pris une dernière fois à gauche sur le dessus du chemin, n’hésitez pas à vous retourner pour découvrir les vallons mêlés de forêts et de pâtures.Au premier bâtiment, prenez à droite et restez sur ce chemin parallèle à la ligne du sommet. Il vous conduit en direction de Fanzel. Au début la vue est dégagée et porte vers les ondulations naturelles de ce beau paysage. Arrivé dans le modeste bois de chênes un peu rabougris par la difficulté de vivre dans un sol pauvre, vous descendez avec prudence parmi les affleurements de schiste&nbsp;jusqu’ aux premières prairies de Fanzel.&nbsp;Un tronçon asphalté vous conduit de la première ferme à la route plus importante de l’Estinale, en face du château-ferme.C’est là, près de cette petite chapelle à l’abri de la maison, que vous empruntez&nbsp;la route vers la droite. A proximité de la dernière habitation sous une petite falaise schisteuse, une petite potale dédiée à Notre-Dame de Lourdes résiste au temps qui passe. Vous arrivez&nbsp;au « S » du pont, après lequel vous prenez à gauche vers la ferme du Stockay. Sans vous souciez des autres chemins, vous grimpez le long des prés et de la forêt, jusqu’au sommet de la colline où apparait au loin le village de Clerheid. Au carrefour prendre à droite vers le bois mélangé de Baudrissart.&nbsp;De temps à autre, à gauche, dans une échancrure sylvestre,&nbsp;s’encadre&nbsp;au loin, de nouveau, le village de Clerheid. Avant le village d’Estiné, en sortie de la tranchée, reprendre à droite le chemin pentu et caillouteux durant cinq cents mètres. Alors, le petit sentier à gauche qui vous permet de dégringoler vers le Pont des Soupirs qui enjambe l’Estinale.&nbsp;Traversez la route pour parcourir un autre sentier bucolique qui vous ramène à la Rampe des Crétalles, regagnez la place d''Erezée où se trouve votre point de départ.Cette promenade fait partie de la carte pédestre Erezée-Manhay disponible dans nos bureaux d''accueil ou commandable en ligne sur https://www.coeurdelardenne.be/shop'),
