    ('gpx/20040.gpx', 'Newie-Gresford-Lostock-Masseys Cr-Upper Allyn River-Chichester-Fosterton SF-Dungog-Newie- April 2024', 'Route - Newies thru Lostock Dam, across to Upper Allyn River, across to Chichester Dam, thru Fosterton SF, Dungog & back to Newie. 
Level - Easy to medium. 
Mix - Probably 65% road, 35% off road (mostly fire trail quality).
Bike - HD Pan America 1250S
Some nice flowing bitumen roads with great farm views, suspension bridge stop at Gresford, dam views at Lostock, dirt road with spectatular views across Masseys Cr Forest, awesome dirt roads thru Upper Allyn & Fosterton State Forest. 
Approx 320km. 7hrs with a few stops along the way.'),
