    ('gpx/23272.gpx', 'Islandeering: Scolt Head Island Circular Walk', 'Islandeering; Scolt Head Island circular
This route travels through a small paradise of sand dunes, salt marsh, mud flats, and shingle. It is internationally important for its birdlife (terns in particular which breed here). This is an adventurous walk that requires tidal crossings and good navigation skills. You need to cross two tidal creeks to get to the island, then cross two more to get back to the mainland. Many families simply cross Overy Cockle Strand at low tide, then spend a few hours on the island beach and walk back; or use the seasonal ferry from Burnham Overy Staithe to keep their feet dry 

By Lisa and Charlie Drewe 

ROUTE 
Start/parking: Car park Burnham Overy Staithe (GR TF 845 443)
Is it for me? It is possible to get to the island’s beach and back by walking across at low tide or using the public ferry. Completing the whole route is for the more adventurous, that are confident of reading tide tables and planning
Stiles: 0
PLANNING 
Nearest town: Burnham Overy Staithe
Refreshments: The Hero, Burnham Overy Staithe; 01328 738334
Public toilets: None 
Public transport: 36 Coastliner Bus
Maps: OS Explorer 250 &amp; 251; OS Landranger 132

From Islandeering, further details and more routes at www.islandeering.com. Copyright Islandeering 2019. All rights reserved. We have taken all reasonable steps to ensure these walks are safe and correctly described. However things do change and all outdoor activities involve a degree of risk. The GPX trace on this route is for use as a guide only, its accuracy may change depending on the scale of map you are using. Use in combination a paper map and good knowledge of tide times. The publishers accept no responsibility for any errors or omissions or for any injuries or accidents that occur whilst following this walk.'),
