    ('gpx/23289.gpx', '[Itinéraire] Tour du Cap Ferrat', '<ol>
<li>Depuis le port de Saint-Jean-Cap-Ferrat,</li>
<li>Emprunter l''avenue Cl. Vignon (b.37),</li>
<li>Quitter l&rsquo;avenue (b.39) pour prendre l&rsquo;all&eacute;e menant &agrave; une carri&egrave;re abandonn&eacute;e (b.38),</li>
<li>Suivre une large voie ciment&eacute;e en direction de l''extr&eacute;mit&eacute; d&eacute;nud&eacute;e de la presqu''&icirc;le,</li>
<li>Longer les jardins et terrasses autour de la piscine du grand h&ocirc;tel,</li>
<li>Se faufiler entre les rochers d&eacute;chiquet&eacute;s et monter les escaliers (fontaine - b.40) jusqu''au phare,</li>
<li>Suivre le sentier en encorbellement le long de la c&ocirc;te occidentale (b.41),</li>
<li>Sortir par les escaliers pour contourner un immeuble b&acirc;ti en bord de mer (b.42),</li>
<li>Poursuivre jusqu''&agrave; Passable (b.43) pour remonter (b.44) jusqu&rsquo;&agrave; la RM 25 (b.681),</li>
<li>Traverser avec prudence (b.680),</li>
<li>Descendre vers le port et de St-Jean-Cap-Ferrat (b.29).</li>
</ol>Modifié: 18 semaines'),
