    ('gpx/23299.gpx', 'Adidas TERREX KMF 25km Trail Run FINAL', 'The 25km Trail Race is graded Ã¢ÂÂHardÃ¢ÂÂ and sits almost halfway between the 10km & 50km routes in difficulty, ascent & terrain you run on. Technical, fast flowing & rugged trails take you around Derwent Water and the Borrowdale Valley with the Watendlath Valley thrown in for good measure.

Want more than the 10k, but not up for the 50k Ultra Marathon, then enter the 25k. It will test you to your limit or get you set for longer trails later in the season.

The route is fully marked with Red Flags and A5 ArrowÃ¢ÂÂs in KMF Pink/Blue colours!

Distance: 25km
Ascent: 866m'),
