    ('gpx/23460.gpx', 'Nisramont: un lac fascinant', 'Balisage: losange rouge Départ: Parking du Barrage de Nisramont  Les lacs fascinent et attirent tous les amoureux d’une nature mystérieuse. À ceux qui cherchent la solitude d’un paysage parmi les plus sauvages de Belgique, celui de Nisramont ouvre grand ses bras.  Venir en Haute Ardenne, c’est humer encore un peu le souffle de l’aventure : le sentier qui longe les rives du lac de Nisramont vous ouvre les images d’une nature sauvage. Cet itinéraire vous emporte vers des ambiances venues d’ailleurs, des lacs du Grand Nord ou de montagne, confirmées par un sentier qui ne se contente pas de suivre les rives de l’Ourthe. Passant de rochers en rochers, vous gravirez des escaliers et descendrez des sentiers escarpés pour rejoindre l’autre rive, près d’Engreux. Le retour via les rives de l’Ourthe orientale vous demandera encore 2 heures de marche mais vous comblera : aucune route, aucun bruit de circulation ne viendront troubler cette magnifique randonnée.  Pour plus de d''itinéraires de randonnées, allez sur https://visitwallonia.be/fr-be/3/jaime/promenades-et-randonnees'),
