    ('gpx/23684.gpx', 'ZTR SUB2 21KM Challenge 2026', 'Sub2 Challenge – Break the Barrier

The Sub2 Challenge is built for runners chasing one goal: finishing the half-marathon in under two hours. This is not just a race—it’s a test of discipline, pacing, and mental toughness.

With an average required pace of 5:41 per kilometer, participants must stay focused from the gun start to the finish line. Every split matters. Every second counts.

Two loops. One mission. Sub-2 or nothing.'),
