    ('gpx/23745.gpx', 'De Condroz: land van Kerken en Kastelen', '<p>Deze halvedagroute start en eindigt in Ciney en neemt je mee door het golvende landschap van de Condroz. Verwacht je aan authentieke Ardense dorpjes, pittoreske kerken en kastelen en een fijne mix tussen kleine weggetjes en uitdagende bochten. De Ardennen op z''n best! </p>

<p>Deze route brengt je onder meer langs: </p>

<ul>
    <li>Het kasteel van Spontin</li>
    <li>Het kasteel van Carondelet</li>
    <li>De ruïne van Montaigle</li>
    <li>De abdijkerk van Hastière</li>
    <li>De heilzame Fontein van Sint-Hadelin</li>
    <li>Dinant en natuurlijk: Ciney</li>
</ul>

<p>Deze route werd met zorg samengesteld door Wim Depraetere in opdracht van Motoren &amp; Toerisme. Het bijhorende toerverhaal lees je op www.motoren-toerisme.be.</p>'),
