    ('gpx/25065.gpx', 'Trasa Mistrzostw Gminy Kąty Wrocławskie w Biegach Przełajowych, Sadowice', '🏃‍♂️ Mistrzostwa Gminy Kąty Wrocławskie w Biegach Przełajowych 🌲 to cykl 4 biegów zorganizowanych w różnych miejscowościach gminy. 

Trasy o długości około 5-7 km prowadzą przez malownicze tereny Parku Krajobrazowego Doliny Bystrzycy, oferując uczestnikom wyjątkowe wyzwania 💪, takie jak podmokłe tereny 🌧️, kręte leśne ścieżki 🌿 oraz naturalne przeszkody 🌳 (powalone drzewa, wystające korzenie itp.).

📅 Trzeci bieg z cyklu odbędzie się w niedzielę, 1 czerwca 2025.

Lokalizacja 📍 :
    🏁 Start i meta: Sadowice, Świetlica Wiejska, ul. Nowe Osiedle
    ⏰ Godzina: 11:00'),
