    ('gpx/25801.gpx', 'Kortenhoefse Plassen kanoroute', '<p>Deze route van Natuurmonumenten voert je door een van de rustigste en fraaiste stukjes van het Vechtplassengebied. De Kortenhoefse Plassen zijn alleen toegankelijk voor kano’s en roeiboten. <br/>
<br/>
De Kortenhoefse Plassenroute is aangegeven met blauwe palen met gele nummers en duurt ongeveer 2,5 uur. Bij een van de kanosteigers kun je gemakkelijk opstappen of overstappen.<br/>
<br/>
Startpunt: parkeerplaats Kortenhoef langs N201 en bij kanoverhuurders.<br/>
<br/>
Ga voor meer routetips, highlights in Gooi &amp; Vecht en verdere toeristische informatie naar de officiële site van de regio: <a href="http://www.vvvgooivecht.nl" rel="nofollow" target="_blank"> www.visitgooivecht.nl </a></p>'),
