    ('gpx/26759.gpx', 'P03 — Il Castello e il Bosco di Capriati a Volturno (OSRM real routing)', 'Percorso P03 Geo-Matese. ANELLO su rete stradale OSM reale.
Piazza Roma › Torre Cesa Iannitti › Santuario San Rocco › Bosco Antico › Piazza Roma.
Sorgente: OSRM Foot routing (router.project-osrm.org) su dati OpenStreetMap.
Lunghezza: 5.97 km | Durata: 22 min | 325 punti traccia.
