    ('gpx/26760.gpx', 'camporells', NULL),
    ('gpx/26762.gpx', '20260531 Vélo en plein air', NULL),
    ('gpx/26767.gpx', 'P09 — Grande Traversata del Matese Casertano · 3 Giorni', 'Traversata multi-giorno originale del Matese casertano (PNRR Geo-Matese).
Giorno 1: Prata Sannita → Gallo Matese  | 17 km · D+500 m · 6–7h
Giorno 2: Gallo Matese → Lago del Matese | 18 km · D+400 m · 6–7h
Giorno 3: Lago del Matese → Capriati    | 17 km · D+200 m · 5–6h
Totale: ~52 km · D+2469 m · 2716 trkpt · Difficoltà E/EE.

Coordinate ricostruite da: Wikipedia, ISTAT, Wikiloc (Sentiero delle Fate/Cascate Lete),
CAI Piedimonte Matese, Komoot guide Parco Matese, GuideSlow Matese, MiC Catalogo,
analisi morfologica OSM.

⚠ TRAVERSATA ORIGINALE — Nessuna traccia GPX pubblica preesistente.
RILIEVO GPS IN CAMPO OBBLIGATORIO su 3 giornate (Voce A §3.1.1 Cap. M4).
Dopo il rilievo: pubblicare su Komoot come "Tour" multi-giorno e su Wikiloc.
CUP: E14H25000590006 | Progetto PNRR M2C1 Green Communities | Geo-Matese 2026.
Difficoltà: E (Escursionisti) per G1/G3 · EE (Escursionisti Esperti) per G2.
Guida escursionistica fortemente consigliata per il Giorno 2 (quote > 1.400 m).'),
