    ('gpx/26884.gpx', 'n18-serre-renard', '<ol>
<li>Au d&eacute;part de la gare SNCF, se diriger vers Intermarch&eacute;, puis emprunter le passage &agrave; niveau et poursuivre &agrave; gauche, avant le passage &agrave; niveau prendre &agrave; droite en direction de "Le Fein".</li>
<li>Lorsque le chemin redescend, prendre &agrave; droite pour rejoindre "Les Olliviers". Apr&egrave;s avoir pass&eacute; la chapelle, prendre compl&eacute;tement &agrave; gauche sur une plus large route, la continuer sur plus d''un kilom&egrave;tre avant de s''engager sur un single track du cot&eacute; gauche de la route.&nbsp;</li>
<li>Tourner &agrave; droite en direction du Col Lebraut, puis apr&egrave;s quelques kilom&egrave;tres prendre une piste carrossable &agrave; droite. Continuer sur le chemin le plus large et passer la cabane foresti&egrave;re du "Champ du Comte" et la "Croix des Sept Fr&egrave;res".</li>
<li>A la cabane du "Clot Clavary" prendre le chemin du milieu alternant mont&eacute;es et descentes jusqu''au belv&eacute;d&egrave;re. Puis prendre le chemin qui serpente jusqu''au Col Lebraut o&ugrave; le chemin se poursuit sur la gauche par une courte mont&eacute;e.</li>
<li>Arriv&eacute; au dernier belv&eacute;d&egrave;re, au-dessus des "Hyvans" continuer tout droit en direction du barrage. Aux "Hyvans" rejoindre la route qui remonte &agrave; gauche.</li>
<li>Apr&egrave;s quelques kilom&egrave;tres sur la route, la quitter pour rejoindre un sentier qui s''enfonce dans la for&ecirc;t. Prendre la seconde route sur quelques m&egrave;tres pour la traverser, puis continuer sur le sentier.</li>
<li>Rejoindre la route &agrave; droite, puis la suivre en direction de "Chorges". Arriver au niveau du club h&ocirc;tel "Les Horizons du lac" quitter la route principale pour aller en direction du "Villard". Gagner le chemin montant sur la gauche et traverser l''ensemble des champs et la voie ferr&eacute;e.</li>
<li>Regagner la route sur la gauche et continuer tout droit jusqu''au passage &agrave; niveau. Apr&egrave;s le passage &agrave; niveau tourner &agrave; droite et retrouver l''itin&eacute;raire de d&eacute;part dans le sens inverse.&nbsp;</li>
</ol>Modifié: 2 semaines'),
