    ('gpx/27128.gpx', 'Beacons Batch or Black Down Hill Circular Hike, through Rowberrow Warren Wood, Mendip Hills, Somerset', 'Beacon Batch is the highest point in the Mendip Hills Area of Outstanding Natural Beauty. From the trig point, you get breathtaking panoramic views that stretch over the Bristol Channel into Wales, over Weston-super-Mare, the Chew Valley and across the Mendips. There are Bronze Age burial mounds at the summit, too. A very special place with lots of great walking to enjoy all around.'),
