    ('gpx/27485.gpx', 'Foel Fenli and Moel Famau from Loggerheads', 'The Clwydian Hills are often ignored by walkers as they head for the bigger peaks in the nearby Snowdonia National Park. Moel Famau (554 m) is the highest peak in the range and provides excellent views in all directions often having the advantage of being below the cloud base when higher summits are hidden from view.'),
