    ('gpx/27564.gpx', 'Brontes in Pendle', 'Distance: 7km (4.5miles).
Time: 3-4 hours.

Walkers may also be interested to know that you can extend the walk by climbing Boulsworth Hill to enjoy breathtaking views and see some natural gritstone sculptures. To climb Boulsworth Hill, follow the way-marked concessionary route (starting/finishing at point 5). Lad Law (marked by a triangulation point) is at the top of the hill. (Distance: 3km/2 miles)

This circular route covers a variety of terrain, and you are likely to encounter some muddy streches. Weather conditions can change suddenly, so be prepared for all evetualities:

• Wear stout, waterproof boots
• Take waterproof clothing
• Carry a compass and map
• Inform someone of your route
• Allow plenty of time
• Keep dogs on a lead across farmland and under close control at all other times'),
