    ('gpx/27823.gpx', 'Sougliani Path 13km (Stratoniko Oros)', 'Sougliani Path 12km: Description

The Sougliani Path route starts at 10:45 a.m. on the Stavros pedestrian street, at an altitude of 0m. The route initially starts on an asphalt road for 800m. Then, the runners enter a slightly uphill forest road for 1.070km and reach the beginning of the marked trail No. 5, which they follow. This is a narrow, technical trail. Reaching the 1st Station (Sykia Petra area), they have run the first 3.5 km of the route. The altitude of this area is 400m.
After this stop at the 1st Station, the participants follow trail No. 5 again and then trail No. 4, reaching the peak of Prophet Elias at an altitude of 665m and a total distance of 5.9 km. From that point onwards, a descent begins, initially steep but then smoother, leading the participants to the 2nd Station (Paliochora area) at 8.2 km and an altitude of 470m.
At this point, they will have completed 8.2 km of distance. The route now puts the runners on trail No. 3, where they will descend approximately 220 wooden steps, built by the Stavros Mountaineering Association. The end of the trail leads them to Ano Stavros, specifically to the Agnant area at an altitude of 90m. Up to here, the route includes 11 km. Finally, the participants will cross the village of Ano Stavros for 2.3 km to reach the starting point, at the end of the pedestrian street, which is also the finish line. The total length of the route is 12 km. Of these: 9 km are trail (69.2%), 1.1 km are forest road (9.1%), 2.9 km are asphalt (22.8%). The total elevation gain of the route is Ascent: 750m, Descent: 750m.'),
