    ('gpx/27939.gpx', 'Tulln - Vienna-Nussdorf, violet route', 'Cycle tour in total 37 km / 23 miles Itinerary Cycle tour Tulln - Vienna-Nussdorf Ship docking Tulln arrival 09:00 am, departure 10:00 am Vienna-Nussdorf arrival 01:00 pm (approximate values, subject to change without notice, please check the announcements on board) Right in front of Vienna&apos;s entrance, embedded in a breathtaking landscape, the monastery of Klosterneuburg is situated. You can already see the cupola of this 900-year-old baroque building from a distance. &quot;Kahlenbergerdorf&quot; with its wine taverns is definitely worth a visit. A short hike through the vineyards leads to the Kahlenberg viewing terrace, where you&apos;ll be rewarded with a stunning view of the vibrant metropolis below.'),
