    ('gpx/27953.gpx', '[Itinéraire] Pont des Camisards', '<br />
<ol>
<li>Prendre la voie verte en direction du P&ocirc;le M&eacute;canique. Vous apercevrez la colline de l''Ermitage et le crassier, vestige des mines de charbon</li>
<li>Au rond point du Moulinet suivre toujours la voie verte en direction du P&ocirc;le M&eacute;canique, observez le chevalement de la mine de Fontane sur la droite</li>
<li>Au rond point prendre la direction du Soulier, hameau o&ugrave; existait une usine &agrave; chaux</li>
<li>Au croisement prendre &agrave; droite direction la Vabreille</li>
<li>Prendre sur la passerelle, suivre le balisage et rejoindre la D916 avec vue imprenable sur le hameau de la Tour, avec son Ch&acirc;teau et sa Chapelle du 17&egrave;me si&egrave;cle.</li>
<li>Prendre &agrave; gauche direction Cendras</li>
<li>Prendre &agrave; droite Avenue Jean Moulin, suivre le balisage puis chemin de la Vig&egrave;re.</li>
<li>Suivre direction Malataverne tout droit et traverser le hameau</li>
<li>Prendre &agrave; Gauche direction pont des Camisards, datant du 17&egrave;me si&egrave;cle</li>
<li>Passer sur ce magnifique pont, prendre &agrave; gauche et suivre la direction Al&egrave;s</li>
<li>Au croisement prendre direction la Blaqui&egrave;re</li>
<li>Poursuivre direction Al&egrave;s</li>
<li>Suivre le balisage Al&egrave;s centre et rester sur la voie verte au pont de Brouzen pour rejoindre le parking de d&eacute;part</li>
</ol>Modifié: 6 semaines'),
