    ('gpx/28430.gpx', 'St James’ Way Camino - full OS route from Reading to Southampton', 'This is the official ‘St James’ Way’ route designed by the Confraternity of St James UK. It is the route
that is marked up on Ordnance Survey Explorer and Landranger maps.

Camino pilgrims seek to venerate Saint James the Apostle, whose tomb is found at the magnificent Santiago de 
Compostela Cathedral in Northern Spain.  Although today, souls from all religious and cultural beliefs and backgrounds embark on this pilgrimage.

The St James’ Way is a modern-day Camino pilgrimage route in England. It runs from St James Church in Reading to God’s House Tower in Southampton and takes between 4-6 days to walk.

A medieval pilgrim would typically have followed this route to Santiago after visiting Reading Abbey, the centre of the St James cult in the Middle Ages owing to the reputed ‘Hand of St James’ relic kept by the monks. From the port of 
 Southampton, they would naturally continue their passage by boat to Ferrol or the vibrant city of A Coruña. On the shores of Galicia, they picked up their journey on the Camino Inglés (English Way) route.  Pilgrims from Ireland and Scandinavia also followed this route to Santiago.  

At certain points, walkers may want to venture off the official route to visit sites of interest, such as, at Silchester, completing their walk around the walls of the Roman City, rather than veering off through open fields, to Church Lane on their way to St James Church in Bramley, with the largest pilgrim stamp on the whole Camino network of paths. These alternatives, along with the places visited, are described in the CSJ’s guidebook to the route, ‘A Pilgrim Guide to St James’ Way’.

The route meanders along rivers, canals and across an ever-changing seasonal countryside passing through villages, towns, and cities before entering the Itchen estuary to Southampton Water and the open sea. The quintessentially English pubs that line the route give as much refreshment to the spirit of pilgrims as its churches!

As regards its walking difficulty, the route is almost entirely flat. Its highest point at 184m is at the start of the Oxdrove Way, a straight road (now a track) made by the Romans. A mile before this high point with panoramic views, is the 12th -century church of St James’s in Upper Wield, and 4 miles
after it is the adorable Hampshire town of Alresford, famous for its watercress and the Watercress Line, a big draw for locomotive enthusiasts.

Just after Winchester Cathedral and College, the route passes The Hospital of St Cross, which still offers the Wayfarer’s Dole – bread and ale – to poor pilgrims in need of refuge. 

At Southampton, the ‘Via de Sanctus Iacobus’ may be claimed at either God’s House Tower or Tudor House & Garden (located on Bugle Street, near GHT) by pilgrims with stamps in their pilgrim passport from Reading. This certificate is an acknowledgement of their achievement of having
walked the whole of the St James’ Way, similar to the ‘Compostela’ issued by the Pilgrims’ Office in
Santiago.  Some pilgrims may wish to cross the water to A Coruna in Northern Spain to continue their pilgrimage along the Spanish Camino Inglés, to Santiago de Compostela. 

The route is also continuously waymarked from start to end by distinctive ‘Camino Inglés to Santiago’ signs that hold a directional yellow arrow and stylised scallop shell; the symbol of a pilgrim. 

Have a great journey! Or, as the Spanish say, “Buen Camino!”'),
