    ('gpx/28487.gpx', 'Circuit Forêt d''Exception® - Le sentier de Douaumont', 'Parcours découverte de Douaumont : un voyage entre histoire et nature Découvrez Douaumont et ses environs lors d''une balade immersive de 2 km, idéale pour les passionnés d''histoire et les amoureux de la nature. Départ au Fort de Douaumont : Commencez votre aventure au cœur de ce monument emblématique de la Première Guerre mondiale. Suivez le Boyau de Londres : Marchez sur ce sentier historique, autrefois essentiel aux soldats, et ressentez l''atmosphère de ce lieu chargé de mémoire. Explorez la Forêt d’exception de Verdun : Laissez-vous envoûter par cette forêt majestueuse, reconnue pour sa richesse écologique et son histoire. En chemin, ne manquez pas l’abri TD3, témoin discret des conflits passés. Point culminant au belvédère du Fort de Douaumont : Terminez votre parcours en beauté au belvédère, d''où vous pourrez contempler une vue inédite sur la contrescarpe ouest et les fossés du fort. Une perspective unique sur l''ouvrage qui vous permettra d’apprécier toute sa grandeur et son importance stratégique. Rejoignez-nous pour une promenade enrichissante qui allie beauté naturelle et mémoire historique, en plein cœur de Douaumont.'),
