    ('gpx/28555.gpx', 'Gross Glockner', 'Mijn heenrit vanuit Hinterstoder naar de Gross Glockner ... (Kaiser-Franz-Josefp-hohe)

Daar is het genieten van het op/afrijden van die baantjes (ik heb sommige strekken 4 keer gedaan ... ;)) ) 
Tijd te kort ... Infeite moet je voor een Gross-Glockner (moto) bezoek, een volle dag uittrekken. 

Een terugrit uitstippelen was dus zinloos ... de snelste weg terug.


Hoe korter je bij het vertrekpunt kan verblijven, hoe beter.
Tol was een 25 Euro ... maar je krijgt waar, voor je geld. (goed onderhouden biljart-asfalt) alle elke 2-300 meter een uitwijk-stop mogelijkheid om om te genieten van de panorama''s ...)


absolute aanrader !!!'),
