    ('gpx/28675.gpx', '23b The Dragons Back - alternative route', 'GPX file from Vertebrate Publishing; file is copyright Vertebrate Publishing and must not be publicly shared on other websites. Do not remove this notice.

While every effort has been made to ensure the accuracy of these GPX files, things change and we are unable to guarantee that every detail will be correct. Please exercise caution if a direction appears at odds with the route on the ground. A comparison between the GPX file and a map should see you on the right track.

Every effort has been made to achieve accuracy of the information in these GPX files. The authors, publishers and copyright owners can take no responsibility for: loss or injury (including fatal) to persons; loss or damage to property or equipment; trespass, irresponsible behaviour or any other mishap that may be suffered as a result of following these route. The inclusion of a track or path as part of a route, or otherwise recommended, in these GPX files does not guarantee that the track or path will remain a right of way. If conflict with landowners arises we advise that you act politely and leave by the shortest route available. If the matter needs to be taken further then please take it up with the relevant authority.'),
