    ('gpx/28772.gpx', 'SWME Bakewell and Dovedale: Monsal Head and Little Longstone', 'This walk forms part of Ordnance Survey&#39;s &#39;Short Walks Made Easy&#39; series, which offer leisurely walks between 1 and 5 miles, with simple to follow step-by-step instructions; essential logistical information including accessibility, parking &amp; dog suitability; fascinating local information and nature guides; and stunning photography.

The view from Monsal Head over the viaduct and down into the valley is one of the best-known viewpoints in the Peak District National Park, and arguably the most photographed. This walk takes you down into the dale and along the delightful River Wye. The view from the viaduct is nearly as good as the one from the head of the dale, and there’s also the excitement of walking through the longest tunnel on the Monsal Trail.

To buy the Short Walks Made Easy: Bakewell &amp; Dovedale guide in which this walk features, head to <a href="https://shop.osmaps.com/bakewell-dovedale-short-walks-guidebook-os-short-walks-made-easy/" rel="nofollow">https://shop.osmaps.com/bakewell-dovedale-short-walks-guidebook-os-short-walks-made-easy/</a> or to browse the entire &#39;Short Walk Made Easy&#39; range, visit <a href="http://os.uk/SWME" rel="nofollow">http://os.uk/SWME</a>'),
    ('gpx/28773.gpx', 'SWME Bakewell and Dovedale: Monsal Head and Little Longstone', 'This walk forms part of Ordnance Survey&#39;s &#39;Short Walks Made Easy&#39; series, which offer leisurely walks between 1 and 5 miles, with simple to follow step-by-step instructions; essential logistical information including accessibility, parking &amp; dog suitability; fascinating local information and nature guides; and stunning photography.

The view from Monsal Head over the viaduct and down into the valley is one of the best-known viewpoints in the Peak District National Park, and arguably the most photographed. This walk takes you down into the dale and along the delightful River Wye. The view from the viaduct is nearly as good as the one from the head of the dale, and there’s also the excitement of walking through the longest tunnel on the Monsal Trail.

To buy the Short Walks Made Easy: Bakewell &amp; Dovedale guide in which this walk features, head to <a href="https://shop.osmaps.com/bakewell-dovedale-short-walks-guidebook-os-short-walks-made-easy/" rel="nofollow">https://shop.osmaps.com/bakewell-dovedale-short-walks-guidebook-os-short-walks-made-easy/</a> or to browse the entire &#39;Short Walk Made Easy&#39; range, visit <a href="http://os.uk/SWME" rel="nofollow">http://os.uk/SWME</a>'),
