    ('gpx/28849.gpx', 'Töddenland-Radroute', 'Der Töddenradweg verbindet auf rund 120 Kilometern historische Handelsrouten der Tödden zwischen Rheine und Osnabrück. In Ibbenbüren führt die Route durch den Stadtteil Laggenbeck und vorbei an alten Handelswegen, typischen Ackerbürgerhäusern und stillen Waldpassagen. Informationstafeln entlang des Weges geben Einblicke in das Leben und Wirken der wandernden Kaufleute im 17. und 18. Jahrhundert.Durchfahren werden Ibbenbüren, Hopsten, Recke und Mettingen im Tecklenburger Land sowie Schapen, Beesten, Messingen, Thuine und Freren im Südlichen Emsland.'),
