    ('gpx/28880.gpx', 'THE CAPITOL 5-MILE COURSE', 'Start on East Capitol Blvd and run one lap around State Capitol. Run north to intersection, turn left onto 500 north, take to Columbus and turn left (south), take to 300 West and make a left, run back to East Capitol Blvd.  Run north, past start line to 500 North. Veer right onto Bonneville Blvd. Continue north all the way past City Creek Canyon entrance, then head south.  Once  you make the turn south, head right, into Memory Grove.  Run 400 yds until turnaround and return to Bonneville Blvd.  Continue south until entrance of Salt Dome. (3-mile mark) Turn right into parking lot. (Water Station)  One lap around parking lot and then back onto Bonneville Blvd.  Head south until turnaround at 11th Ave. Return north on Bonneville Blvd.  Continue past Memory Grove entrance and past City Creek entrance, then continue south on Bonneville Blvd. all the way to 500 North intersection of State Capitol.  Then continue south on East Capitol Blvd. to the finish line. (common start & finish line)'),
