    ('gpx/29266.gpx', 'Looproute Aalst - Aquatopia - Groene lus', '<p>Deze looproute heeft zijn startpunt aan het zwembad Aquatopia, Zwembadlaan 2 in Aalst en biedt met 2 lussen een verscheidenheid aan afstanden:</p>

<p><strong>Groene Looplus</strong>: Deze route is 5,7 km lang en bestaat voor maar liefst 56% uit onverharde paden.<br/>
We starten deze route op de parking van Aquatopia en lopen via het zwembadpark verder in het noordelijk deel van Aalst. Na passage aan sportcentrum Beukenhof, kan er via de Finse piste terug worden gelopen naar het startpunt</p>

<p><strong>Blauwe Looplus:</strong> Deze route is 8,35 km lang en bestaat uit 70% onverharde paden. De route neemt je mee langs het Heuvelpark en sportcentrum Zandberg. Er is onderweg een kleine uitbreiding mogelijk voor wie graag nog wat extra meters in het bos loopt. Na 1,5 km op de blauwe lus kan je ter hoogte van natuurgebied Gerstjens inpikken op één van de looproutes aan Denderdal. Zo kan je je loopje uitbreiden tot een langere afstand.</p>

<p>Kenmerken:</p>

<p>Beloopbaarheid tijdens nattere perioden : goed beloopbaar</p>

<p>Mate van aanwezigheid verlichting: gedeeltelijk</p>

<p>Moeilijkheidsgraad: makkelijk</p>'),
