    ('gpx/29395.gpx', '1. Etappe Hildegard von Bingen Pilgerwanderweg: Idar-Oberstein - Herrstein', 'Die 1. Etappe des Hildegard von Bingen Pilgerwanderweges ist sehr anspruchsvoll und durch eine abwechslungsreiche Wegeführung mit starkem Gefälle gekennzeichnet.
