    ('gpx/29512.gpx', 'Châteaudun - Le bois des Gâts à Châteaudun', 'Le cheminement vous fera découvrir Châteaudun sous tous les angles,  depuis le centre-ville, dominant la vallée de 60m, jusqu''au bord du  Loir, à travers le bois des Gâts, espace naturel préservé. Mais cela se  mérite et vous devrez compter les 200 marches !'),
