    ('gpx/29522.gpx', 'Snowdonia: Dolgellau to Bala via Cader Idris', 'Linear two-night challenge from Dolgellau over Cader Idris to Bala, planned for 12–14 Aug 2026. Built using OpenStreetMap/BRouter path geometry, Eryri National Park Pony Path and Llanfihangel route references, the 2026 Mary Jones Walk guide, and the Outdooractive community trace by Mark de la Mare. Includes the official Mary Jones footpath option on the final leg rather than the shorter B4403 alternative. Verify against OS Explorer OL23 and current closures. GPX is an aid, not a substitute for map, compass, weather judgement or landowner permission. Wild camping in Eryri requires the landowner''s permission.'),
