    ('gpx/29551.gpx', 'Valgrosina Trail 12k', 'La gara piu'' breve, dove poter spingere dal primo all''ultimo km. Partenza alle ore 8.30 dalla Piazza del Comune di Grosio. Dopo un breve tratto sulla via principale, inizia la salita, che si fa subito seria, per raggiungere pendenze da vertical prima del passaggio che costeggia la Cannoniera (1000 m s.l.m). Da qui si alternano tratti di dura ascesa ad altri in minor pendenza, con alcuni punti molto panoramici, che in circa 5 km conducono alla localita'' Pra del Poda (1470 m s.l.m.), dove finalmente si inizia a scendere, su uno stretto sentiero che vertiginosamente conduce alla chiesetta di S. Giacomo (1050 m s.l.m.). Da qui, seguendo la vecchia strada si raggiunge in poco piu'' di 1 km l''abitato di Ravoledo, proseguendo poi verso il Castello Visconteo, e da li'', percorrendo la via S.Faustino, l''ultimo tratto di gara, dove sara'' battaglia tra chi vorra'' tagliare per primo il traguardo posto presso il parco della Villa Visconti Venosta.'),
