    ('gpx/29661.gpx', 'Seaford to Eastbourne (The 7 Sisters) Walk SWC-Walk-2-28 #swcwalks COPYRIGHT 2025 SATURDAY WALKERS CLUB ANDREW MURPHY ALL RIGHTS RESERVED WWW.WALKINGCLUB.ORG.UK', '<p>The best walk in the Southeast! A dramatic cliff walk passing Cuckemere Haven, the Seven Sisters and Beachy Head as the South Downs meets the sea. Ends with Eastbourne''s promenade and pier.</p><p>This route was created by the Saturday Walkers Club. It is fully written up at <a href="https://www.walkingclub.org.uk/walk/seaford-to-eastbourne/">https://www.walkingclub.org.uk/walk/seaford-to-eastbourne/</a> #swcwalks</p><p> COPYRIGHT 2025 SATURDAY WALKERS CLUB ANDREW MURPHY ALL RIGHTS RESERVED WWW.WALKINGCLUB.ORG.UK </p>'),
