    ('gpx/29861.gpx', 'Luirojärven kierros 4.-10.9.2026', 'Rastipisteet ovat tarkkoja (Metsähallitus / nuotiopaikat.fi / Eräluvat). REITTIVIIVAT OVAT SUORIA SUUNNITTELULINJOJA PISTEIDEN VÄLILLÄ, EIVÄT MAASTOSSA KULKEVA POLKU. Reittiä ei ole merkitty maastoon. Kulje kartan ja kompassin mukaan, ei tätä viivaa pitkin.'),
    ('gpx/29862.gpx', 'Volta a Portugal em Bicicleta 2026 - Stage 10', NULL),
    ('gpx/29863.gpx', 'Luirojärven kierros 4.-10.9.2026', 'Yksi yhtenäinen jälki koko kierroksesta, lisäksi Sokostin päiväretki, 9 rastipistettä ja 7 päiväetappia. RASTIPISTEET OVAT TARKISTETTUJA. JÄLKI ON SUORIA SUUNNITTELULINJOJA PISTEIDEN VÄLILLÄ, EI MAASTOSSA KULKEVA POLKU. Reittiä ei ole merkitty maastoon: kulje kartan ja kompassin mukaan, älä tätä viivaa pitkin.'),
