    ('gpx/29896.gpx', '262 YHA Edale - Kinder Scout Plateau', 'Welcome to YHA Walks

Route: 262, YHA Edale - Kinder Scout Plateau

Type of walk: Moorland walk

This walk begins at a YHA hostel – just one of the national charity’s c.150 unique and welcoming properties in England and Wales.

Start/Finish:  SK139865

Hostel details: <a href="https://www.yha.org.uk/hostel/yha-edale" rel="nofollow">https://www.yha.org.uk/hostel/yha-edale</a>

Paper map: OS Explorer 1:25k (OL01) Peak District - Dark Peak area

YHA difficulty grade: 81, see how YHA grade their walks: <a href="https://www.yha.org.uk/festival-of-walking/self-guided-walks" rel="nofollow">https://www.yha.org.uk/festival-of-walking/self-guided-walks</a>

Get the route details here: <a href="https://www.yha.org.uk/sites/default/files/uploads/PDFs/Walking%20Maps%202023/262-yha-edale-activity-centre-kinder-scout-plateau.pdf" rel="nofollow">https://www.yha.org.uk/sites/default/files/uploads/PDFs/Walking%20Maps%202023/262-yha-edale-activity-centre-kinder-scout-plateau.pdf</a>

Find your next adventure at <a href="https://yha.org.uk" rel="nofollow">https://yha.org.uk</a>



This route has been created by YHA to provide inspiration and to aid planning and preparation of your walk. Digital maps are a guide and do not always reflect the conditions on the ground, ensure you are aware of your immediate surroundings. The accuracy of gpx routes vary depending on the scale of the map being used and as such are a guide, they should not be used alone for micro-navigation. YHA&#39;s volunteers have checked all routes but conditions and routes can change throughout the year and over time. All efforts have been made to describe routes accurately in the route cards, but omissions and errors may occur. The route card does not replace the need for an OS Map or the OS Maps App to navigate your walk safely. Walking outdoors involves risk. It is the walker&#39;s responsibility to use their own judgement, to ensure they are prepared for the route and to have suitable equipment and skills. YHA accepts no responsibility for any injuries or accidents that occur whilst following this walk.'),
