    ('gpx/30174.gpx', '[Itinéraire] Sentier Blanc-Martel', '<ol>
<li><img src="/media/upload/Picto_poteau_detoure.png" alt="Poteau" width="19" height="19" />&nbsp;<strong>Chalet de la Maline</strong> - Suivre le sentier qui part du refuge (<img src="/media/upload/network-GR_11.svg" alt="Balisage" />). Apr&egrave;s une travers&eacute;e l&eacute;g&egrave;rement descendante puis quelques lacets, rejoindre le Pas d''Issane. Le franchir par un escalier m&eacute;tallique, et continuer &agrave; descendre sans couper les lacets jusqu''&agrave; une intersection.</li>
<li><img src="/media/upload/Picto_poteau_detoure.png" alt="Poteau" width="19" height="19" />&nbsp;Poursuivre tout droit l&eacute;g&egrave;rement en amont du Verdon. Apr&egrave;s avoir franchi l''&eacute;boulis de Gu&egrave;gues puis &ecirc;tre pass&eacute; par la baume aux Boeufs, d&eacute;boucher sur un carrefour.</li>
<li><img src="/media/upload/Picto_poteau_detoure.png" alt="Poteau" width="19" height="19" />&nbsp;Il est possible d''acc&eacute;der au site de la Mescla, confluence entre le Verdon et l''Artuby, en prenant &agrave; droite (45 min aller-retour). Continuer &agrave; gauche et monter pour acc&eacute;der aux &eacute;chelles de la br&egrave;che Imbert (situ&eacute;es &agrave; la moiti&eacute; du sentier Blanc-Martel). Apr&egrave;s les avoir franchies, continuer en travers&eacute;e puis descendre par une s&eacute;rie de lacets jusqu''au bord du Verdon. Commencer alors une longue travers&eacute;e tant&ocirc;t &agrave; d&eacute;couvert, tant&ocirc;t en sous bois jusqu''&agrave; l''entr&eacute;e du court tunnel de Tresca&iuml;re (110 m). Le traverser puis encha&icirc;ner avec celui du Baou, beaucoup plus long (670 m). Descendre ensuite jusqu''au Verdon, franchir par la passerelle le torrent du Baou et atteindre le parking du couloir Samson.</li>
<li><img src="/media/upload/Picto_poteau_detoure.png" alt="Poteau" width="19" height="19" /> Contourner le parking par la gauche et continuer sur le sentier en direction du Point Sublime. Passer sous la barre rocheuse et monter jusqu''&agrave; un carrefour. Prendre &agrave; gauche, rejoindre la route D952 et la suivre sur la gauche jusqu''au Point Sublime.</li>
</ol><br /><em>Itin&eacute;raire inscrit au Plan D&eacute;partemental de la Randonn&eacute;e des Alpes de Haute-Provence.</em>Modifié: 12 semaines'),
