    ('gpx/30450.gpx', 'Green Road Map Route', 'AUTO-GENERATED ROUTE — IMPORTANT.  This file was produced by the Green Road Map route planner. It may contain errors, omissions, or out-of-date information. The route is not a survey and has not been independently verified.  Roads, byways and rights of way may have changed status, be subject to Traffic Regulation Orders (TROs), seasonal restrictions, temporary closures, or local authority enforcement that this file does not reflect. Conditions on the ground (gates, surface, water levels, obstructions) change frequently and are not represented here.  The user is solely responsible for: verifying the legal status of every section before riding; complying with all applicable laws including the Road Traffic Act 1988 and the Wildlife and Countryside Act 1981; respecting landowner rights, the Countryside Code, and any signage; assessing personal risk, weather, vehicle suitability, and competence.  The Trail Riders Fellowship (TRF), its officers, volunteers, contributors and data partners accept no liability for any loss, damage, injury, prosecution, fine, or claim arising from use of, or reliance upon, this file. The route is provided "as is" with no warranty of any kind, express or implied, including but not limited to fitness for purpose, accuracy, or non-infringement.  Use at your own risk. This file may not be redistributed, resold, or used for commercial purposes without the express written consent of the TRF.  (c) Trail Riders Fellowship — Registered in England and Wales No. 05848933.'),
