    ('gpx/30526.gpx', 'La Boucle du Château de Menthon - cascades de Montviard', 'Cette boucle députe dans le village de Gruffy, le parcours gagne de la hauteur à travers la forêt pour atteindre les cascades de Montviard puis un premier point de vue sur le lac et le massif des Bauges, la descente se fait ensuite sur les hameaux du Bosson puis du Ramponnet et enfin, un beau sentier longe les jeunes vignobles du Château de Menthon Saint-Bernard. 
Cette randonnée pour marcheurs moyens est un beau compromis entre nature et patrimoine rurale.
Informations pratiques : 
Randonnée à ne pas entreprendre en hiver, le bas des cascades est recouvert de glace, la traversée des ruisseaux est dangereuse
parking centre  village face à la mairie.
Chaussures de marche conseillées'),
