    ('gpx/30531.gpx', '„Tour du Mont Blanc“ - The most beautiful hike in Europe through France, Italy and Switzerland.', 'Die Tour du Mont-Blanc ist ein beliebter Fernwanderweg in Europa. Die Tour du Mont-Blanc (auch Mont Blanc-Trail genannt) ist ein Fernwanderweg um das gleichnamige Bergmassiv in den französischen, Italienischen und Schweizer Alpen. Eine unglaublich schöne, aussichtsreiche und manchmal nebelige Wanderung erwartet euch auf der Tour du Mont Blanc. Ich fand die Tour grandios. Chapeau!'),
