    ('gpx/30666.gpx', 'Fietsdodentocht 2026 - 100KM', '<p>Een kleine week vóór de wandelaars van start gaan op de ‘Dodentocht’, is het traditiegetrouw de beurt aan Peloton om al fietsend de straten in en rond Bornem te verkennen. Met twee afstanden om uit te kiezen – <strong>65 km</strong> of <strong>100 km</strong> – is de Fietsdodentocht een gezellige, recreatieve fietstocht voor jong en oud.</p>

<p>Die Fietsdodentocht is een afwisselend traject met glooiende landschappen, rustige wegen en hier en daar een pittige helling voor wie graag de benen test. Of je nu met een stadsfiets, koersfiets of e-bike rijdt, iedereen is welkom!</p>'),
