    ('gpx/30693.gpx', 'Boucle Bikepacking Bordeaux - Gerone (v2, etudiee sur itineraires officiels)', 'Tracé reconstruit a partir des veloroutes officielles reelles : V80 Canal des Deux Mers / Canal de Garonne, V82 Vallee de la Baise, V81 Piemont Pyreneen (Velosud), Pirinexus (Col de Panissars / Via Verda del Carrilet), Eix Pirinenc N-260 (Cerdanya, Alt Urgell), vallee de la Noguera Pallaresa et Port de la Bonaigua, Val d''Aran et Col du Portillon. Chaque point correspond a une ville, un village-etape ou un col reellement traverse par ces itineraires. Le trace reste toutefois un enchainement de points (pas un calque exact du bitume) : pour un fichier 100% colle aux pistes cyclables, importer ces points dans Komoot / RideWithGPS / OpenRunner en mode ''velo de route'' ou ''gravel'' pour un calcul automatique entre chaque etape.'),
