    ('gpx/30795.gpx', 'Bradford Pennine Gateway Trail', 'A linear trail from Ilkley to Haworth, linking the eight sites of the Bradford Pennine Gateway National Nature Reserve. 
Trail devised by Danny Jackson.
An accompanying route guidebook is available. 
Trail launched in September 2026 by Bradford Culture Company.
With thanks to Bradford Council and the Bradford walking community, including Baildon Walkers are Welcome, Bingley Walkers are Welcome, Ilkley Walkers are Welcome, Bradford CHA, the LDWA and Chris Grogan. Additional route mapping and checking by Julia and Ralph Warman of the LDWA.'),
