    ('gpx/4454.gpx', 'Granite peaks 25 - Update 15th April 2024', 'This latest addition to the Irish mountain racing scene takes in the beauty of the Mournes mountain range. The Granite Peaks 25 is the younger sibling of the Granite Peaks Ultra, starting out from Tollymore Forest and along part of the Ulster Way before ascending into the high mountains. No less gruelling and no less spectacular than the Ultra you will transcend part of the Ulster Way (Slí Uladh) before circumnavigating Slieve Bernagh, traversing the shoreline of Ben Crom before returning to the forest of Tollymore. This 25k journey will whet your appetite for the Granite Peaks Ultra, a race you will want to take on once you have experienced the beauty of this landscape.  / Currently 25.0k / y'),
    ('gpx/4455.gpx', 'Granite Peaks Ultra 50K - Update 28th March 2024', 'THis latest addition to the Irish ultra mountain racing scene takes in the beauty of the Mournes mountain range. This 50k ultra (with a 25k younger sibling) starts out from Tollymore Forest and along part of the Ulster Way before ascending into the high mountains. / Amendment. route down to Silent Valley Dam of the Mourne Wall'),
