    ('gpx/8938.gpx', 'Llanwrtyd to Abergwesyn via Tirabad and Llangammarch', 'Road trip around quiet country lanes and villages. There are spectacular views of hills surrounding Llanwrtyd Wells.'),
    ('gpx/8942.gpx', 'Velosport Henley Loop', 'Henley loop return from Velosport shop'),
    ('gpx/8943.gpx', 'Kent Grimpeur', 'Based on one of Audax UK''s classic rides, this is a tough loop around Sevenoaks in Kent. It''s full of classic North Downs climbs like Exedown, Bayleys Hill and the infamous Yorks Hill, the site of the Catford Hill Climb which, it is claimed, is the oldest continuously run race in the world. There are plenty of tea-rooms and pubs on the way round, but you''ll need to make sure you don''t load up too much for the steep, steep climbs and technical descents of the Grimpeur. In the actual Audax events the real hard men do the loop from Otford both ways… feel free to take the train back to London afterwards if you decide to join them.'),
    ('gpx/8944.gpx', 'The Devil''s Punchbowl', 'The Devil''s Punchbowl offers up a longer ride with some of the most spectacular views in the Surrey Hills. 

The route has two notable climbs: the climb up Chalk Lane and Combe Lane through Effingham Forest and a longer climb up Punchbowl Lane to Hindhead Common and the Devil''s Punchbowl.

The route then swings round to drop out of the hills and heading up to the west of Guildford before taking a flat route back to London. 

Starting point: Dish Café, East Molesey. 

Suggested café: National Trust Café at The Devil''s Punchbowl (56km).'),
