    ('gpx/9715.gpx', 'Track-Roundtour Midden Nederland from Zoetermeer', 'Deze route voert je door het midden van Nederland. Met een start- en eindpunt in Zoetermeer gaat de route langs de grote rivieren over de dijken naar de Betuwe en de Biesbosch. 

Deze afwisselende route biedt voor elk wat wils, mooie bochtige dijkjes, polderwegen, hoge bruggen, een veerpont en fraaie plaatsjes. Onderweg is er voldoende gelegenheid om de inwendige mens te versterken.

Ik waardeer deze route met 4 sterren vanwege de mooie wegen, het afwisselende landschap, de natuur en de mooie plaatsjes.'),
