    ('gpx/circular-cambra-d-ase-estacio-esqui-cambre-d-aze-eyne-sant-pierre-dels-forcats-nbqa.gpx', 'Circular Cambra d''Ase - Estació esquí Cambre d''Aze/Eyne/Sant Pierre dels Forcats', 'El Cambra d''Ase (Cambre d''Aze en francès), és un cim de 2.750m d''alçada del límit de l''Alta Cerdanya amb el Conflent, al límit de la comuna cerdanya d''Eina amb les conflentines de Planès i Sant Pere dels Forcats. La part culminant està composta per tres pics que conformen un antic circ glacial. Forma part del Parc Natural Regional dels Pirineus Catalans i en el seu circ es troba l''Estació d''esquí de Cambra d''Ase. En el seu vessant est hi ha la Reserva Natural de la Vall d''Eina. 
 
Està situat a l''extrem meridional del terme de Sant Pere dels Forcats, a la zona sud-oest del de Planès i al sud-est del d''Eina, al nord-oest del Serrat de les Fonts i de la Torre d''Eina i al sud del Puig de l''Home Mort.'),
