    ('gpx/laguna-grande-gredos-v4yj.gpx', 'Laguna Grande Gredos', 'Ruta realizada por la asociación senderista "La vía verde" de Villanueva de la Serena.Es una ruta fácil de seguir,estando señalizada toda ella. 
 
Un día en el circo...de Gredos. 
Salimos de Villanueva a las 7 de la mañana como otras veces. Nos montamos en el autobús entre saludos y bienvenidas. Hasta aquí todo normal, cuando llevábamos un rato en marcha,de repente notamos una fuerte sacudida y el autobús empezó a dar pequeños bandazos,algunos miramos rápidamente por las ventanillas buscando alguna "retroexcavadora de Castuera",pero no, por fortuna era sólo una rueda que había reventado. 
Así que, despacito, muy despacito,dando llantazos y con un portón abierto(que paramos a cerrar por supuesto) llegamos a Trujillo. 
Allí mientras venía otro autobús de Torrecilla de la Tiesa(con eso de la Tiesa nos quedamos con la gana de saber si era por el frío o por el exceso de acaloramiento) nos fuimos a desayunar,así que nos desparramamos por dos bares ,en el mío había buenas mesas tipo salita con su tapetes pidiendo cartas y cojines desparramados,donde una camarera transnochada y malhumorada nos atendió con irritación por nuestra excesiva presencia. 
Proseguimos en el otro autobús,esta vez sin dejarnos ninguna rueda por el camino,con Jesús amenazándonos con su Meteoblue y su terribles 12 gradazos de Gredos,así que tuvimos que parar a comprar abrigo, y algunos optaron por sudaderas de veintitantos eurazos tipo "He estado en Gredos"o algo parecido. 
A las una de la tarde comenzamos la ruta,todo una hazaña tras las grandes peripecias que habíamos sufrido. 
La plataforma es un aparcamiento excavado al final de una larga recta en un vallecito muy feote,en esta fecha, el paisaje apenas nos muestra algunas lomas peladas y rocas de gran tamaño,pero poco más. 
Tras el obligado cartel informativo,empezaba el enemigo de esta ruta,un caminito por llamarle de algún modo, de pedruzcos de diverso tamaño tirados desordenadamente y como decían por ahí "tiradas a mala leche",que iban a castigar nuestros pies durante largos, larguísimos kilómetros... 
El camino sube por el valle para girar a la derecha en lenta y continua ascensión hasta el cártel del Refugio de Reguero Llano,imposible perderse, si miras para otro sitio fuera del camino ,vas de tropezón a trompicón. 
La lapidación podal continua todavía más, cuesta arriba, aunque pasando por algún puentecito que lo hace más bonito,desde luego,el que tuvo la idea del caminito de piedrecitas seguro que no volvió más. 
El castigador tenía en algunos tramos traviesas a modo de vía de tren que nos hacía más fácil el avance. 
Con más alegría que gloria entre el amarillo piorno ,que amenazaba a ratos con engullirnos, llegamos a lo alto de la loma;los Barrerones, que en mi tierra lo llamarían el mirador del ¡Cooooño!, donde se abre ante tus ojos todo el espectáculo del circo de Gredos,picos, piquitos, agujas, neveros, paredes y mucho más... 
Nos recreamos con las fotos, y la nota la dió una cabra montesa posando en lo alto de un risquito apenas a cinco metros de nosotros ,dejándose fotografiar, me quedé esperando que saliera un saltimbanqui del circo o un pastor pasando la gorrilla,pero le pillaríamos echando la siesta. 
Ya por fin cuesta abajo,los pies magullados y la boca abierta, ríachuelos, cascadas,cumbres con pendientes imposibles, todo un circo... 
Se divisaba la laguna de Gredos con el Almanzor arriba, y otros muchos muy parecidos alrededor,con el refugio Elola a la derecha. 
Al llegar a la laguna, hubo gente que decidió quedarse a comer allí,ni sus pies ni su estómagos soportaban más, yo decidí ir a ver a la Elola de cerquita,para lo cual hay que pasar a la izquierda del lago saltándo de piedra en piedra como rana de secano. 
El sitio era increíble, la laguna con sus picos nevados compitiendo por reflejarse en su espejo de agua,ríos por todas partes y el sonido de la montaña susurrando en tus oídos,sólo le faltaba al lago su sirena, o puede que no. 
Comimos,unos en la orillas , otros más por arriba, y nos subimos a la laguna esmeralda, una poza increíble con una cascada en su plenitud de fuerza y belleza. 
Nos volvimos rápidamente, puesto que con lo de la rueda era tarde, y aunque en el paso de las ranas alguno se apostó con su cámara por si alguien quería bañarse con ropa, pasamos sin mojarnos mucho. 
El camino es igual pero a la inversa, en la cuesta que salía del circo, nos preguntábamos entre grandes sudores y sofocos si el meteoblue de Jesús no sería en realidad meteomoon y tenían los satélites al revés apuntando para la luna, y alguno creyó entender mejor el cartel de las sudaderas,no era un "estuve en Gredos" sino "Qué caló en Gredos" y no eran para taparse sino para abanicarse. 
Seguimos cada uno a su ritmo en plan supervivencia con el calvario pedregoso castigándonos los juanetes,eso sí, con las traviesas parecía un videojuego que te tenías que cambiar rápidamente para no estrellarte y perder una vida... 
Por fin en la plataforma, gritaron nuestros pies, nos esperaba el autobús y por fortuna seguía con ruedas.... 
Poco más que contar, llegamos a Villanueva a la hora de las brujas, y nos echamos tantas risas como ampollas teníamos en los pies, aunque de vez en cuando nos acordábamos del ingeniero del caminito de Gredos. 
Volveremos,algunos.'),
